        return searchRandomSuccess(node.getRightChild(), value);
    }

    private static int searchOrderSuccess(NodeType node, int value) {
        tempTimes++;
        if(node.getRecord() == value)
            return tempTimes;
        if(value < node.getRecord())
            return searchOrderSuccess(node.getLeftChild(), value);
        return searchOrderSuccess(node.getRightChild(), value);
    }

    private static void halfAverage() {
        buildHalfSearchArray();
        List<Integer> list = new ArrayList<Integer>();
        for(int value : halfSerachArray)
            list.add(value);
        halfTree = null;
        buildHalfTree(list, true, null);
        int count = list.size();
        halfSuccess = 0;
        for(int value : list) {
            tempTimes = 0;
            halfSuccess += halfSuccess(halfTree, value);
        }
        nullNode = 0;
        halfFailure = 0;
        for(int value = 0; value <= 2048; value += 2) {
            tempTimes = 0;
            halfFailure += halfFailure(halfTree, value);
            nullNode++;
        }
        System.out.println("折半查找成功平均查找长度：" + (double) halfSuccess / count);
        System.out.println("折半查找失败平均查找长度：" + (double) halfFailure / nullNode);
    }

    private static int halfFailure(HalfNode node, int value) {
        if(node == null)
            return tempTimes;
        tempTimes++;
        if(value < node.getValue())
            return halfFailure(node.getLeftNode(), value);
        return halfFailure(node.getRightNode(), value);
    }

    private static int halfSuccess(HalfNode node, int value) {
        tempTimes++;
        if(node.getValue() == value)
            return tempTimes;
        if(value < node.getValue())
            return halfSuccess(node.getLeftNode(), value);
        return halfSuccess(node.getRightNode(), value);
    }

    private static void buildHalfTree(List<Integer> list, boolean left, HalfNode parent) {
        if(list.isEmpty())
            return;
        int mid = list.size() / 2;
        HalfNode node = new HalfNode(list.get(mid));
        if(parent == null)
            halfTree = node;
        else if(left)
            parent.setLeftNode(node);
        else
            parent.setRightNode(node);
        buildHalfTree(list.subList(0, mid), true, node);
        buildHalfTree(list.subList(mid + 1, list.size()), false, node);
    }
}

